// A reassigned function declaration of a module in an import cycle: the
// dependency calls it while the cycle initializes, before this module's
// body runs, and gets the hoisted declaration; later calls see the
// replacement.
import { early, describe } from "./dep.js";

export function format(value) {
  format = function formatUpper(text) {
    return `[${String(text).toUpperCase()}]`;
  };
  return `<${value}>`;
}

export const report = () => [
  "early: " + early,
  "now: " + format("b") + " " + format("c"),
  "dep: " + describe("d"),
];
